    where s.source_url = 'https://www.uscis.gov/working-in-the-united-states/temporary-workers/e-2-treaty-investors'
      and v.is_active
      and (s.visa_type_id is null
           or s.visa_type_id = (select id from public.visa_types
                                 where visaai_id = 'us-treaty-trader-treaty-investor'))
    order by s.visa_type_id nulls last
    limit 1),
  'the investment enterprise may not be marginal. a marginal enterprise is one that does not have the present or future capacity to generate more than enough income to provide a minimal living for the treaty investor and his or her family. depending on the facts, a new enterprise might not be considered marginal even if it lacks the current capacity to generate such income. in such cases, however, the enterprise should have the capacity to generate such income within five years from the date that the treaty investor’s e-2 classification begins.', 'The investment enterprise may not be marginal. A marginal enterprise is one that does not have the present or future capacity to generate more than enough income to provide a minimal living for the treaty investor and his or her family. Depending on the facts, a new enterprise might not be considered marginal even if it lacks the current capacity to generate such income. In such cases, however, the enterprise should have the capacity to generate such income within five years from the date that the treaty investor’s E-2 classification begins.', 'manual', 1.00,
